      "footnotesUr": "[1] ”اسْتَوَىٰ عَلَى الْعَرْشِ“ کا مفہوم اس سے قبل بیان ہو چکا ہے کہ اس سے مراد اللہ تعالٰی کا عرش پر قرار پکڑنا ہے۔ محدثین کا یہی مسلک ہے وہ اس کی تاویل نہیں کرتے، جیسے بعض دوسرے گروہ اس میں اور دیگر صفات الٰہی میں تاویل کرتے ہیں۔ تاہم محدثین کہتے ہیں کہ اس کی کیفیت نہ بیان کی جاسکتی ہے اور نہ اسے کسی چیز سے تشبیہ دی جاسکتی ہے۔ «لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ الْبَصِيرُ»(الشورى: 11)\n[2] اس کے ایک معنی یہ ہیں کہ یہ ایک وقت مقرر تک یعنی قیامت تک اللہ کے حکم سے چلتے رہیں گے جیسا کہ فرمایا «وَالشَّمْسُ تَجْرِي لِمُسْتَقَرٍّ لَهَا ذَلِكَ تَقْدِيرُ الْعَزِيزِ الْعَلِيمِ» (يٰس: 38)۔ ”اور سورج اپنے ٹھہرنے کے وقت تک چل رہا ہے“۔ دوسرے معنی یہ ہیں کہ چاند اور سورج دونوں اپنی اپنی منزلوں پر رواں دواں رہتے ہیں سورج اپنا دورہ ایک سال میں اور چاند ایک ماہ میں مکمل کر لیتا ہے جس طرح فرمایا «وَالْقَمَرَ قَدَّرْنَاهُ مَنَازِلَ» (يٰس: 39)۔ ”ہم نے چاند کی منزلیں مقرر کر دی ہیں“ سات بڑے بڑے سیارے ہیں جن میں سے دو چاند اور سورج ہیں یہاں صرف ان دو کا ذکر کیا ہے کیونکہ یہی دو سب سے زیادہ بڑے اور اہم ہیں جب یہ دونوں بھی اللہ کے حکم کے تابع ہیں تو دوسرے سیارے تو بطریق اولی اس کے تابع ہونگے اور جب یہ اللہ کے حکم کے تابع ہیں تو یہ معبود نہیں ہو سکتے معبود تو وہی ہے جس نے ان کو مسخر کیا ہوا ہے اس لیے فرمایا «لَا تَسْجُدُوْا لِلشَّمْسِ وَلَا لِلْقَمَرِ وَاسْجُدُوْا لِلّٰهِ الَّذِيْ خَلَقَهُنَّ اِنْ كُنْتُمْ اِيَّاهُ تَعْبُدُوْنَ» (فصلت: 37) ”سورج اور چاند کو سجدہ نہ کرو اس اللہ کو سجدہ کرو جس نے انہیں پیدا کیا اگر تم صرف اس کی عبادت کرنا چاہتے ہو“۔ «وَالشَّمْسَ وَالْقَمَرَ وَالنُّجُومَ مُسَخَّرَاتٍ بِأَمْرِهِ» (الأعراف: 54) ”سورج چاند اور تارے سب اس کے حکم کے تابع ہیں“۔",
