      "number": 3,
      "arFull": "وَهُوَ الَّذِیْ مَدَّ الْاَرْضَ وَجَعَلَ فِیْهَا رَوَاسِیَ وَاَنْهٰرًا ؕ وَمِنْ كُلِّ الثَّمَرٰتِ جَعَلَ فِیْهَا زَوْجَیْنِ اثْنَیْنِ یُغْشِی الَّیْلَ النَّهَارَ ؕ اِنَّ فِیْ ذٰلِكَ لَاٰیٰتٍ لِّقَوْمٍ یَّتَفَكَّرُوْنَ ۟",
      "ur": "اسی نے زمین پھیلا کر بچھا دی ہے اور اس میں پہاڑ اور نہریں پیدا کردی ہیں[1] ۔ اور اس میں ہر قسم کے پھلوں کے جوڑے دوہرے دوہرے پیدا کردیئے ہیں[2]، وه رات کو دن سے چھپا دیتا ہے۔ یقیناً غور وفکر کرنے والوں کے لئے اس میں بہت سی نشانیاں ہیں.",
      "en": "And it is He who spread the earth and placed therein firmly set mountains and rivers; and from all of the fruits He made therein two mates; He causes the night to cover the day. Indeed in that are signs for a people who give thought.",
      "footnotesUr": "[1] زمین میں طول و عرض کا اندازہ بھی عام لوگوں کے لئے مشکل ہے اور بلند و بالا پہاڑوں کے ذریعے سے زمین میں گویا میخیں گاڑی ہیں، نہروں دریاؤں اور چشموں کا ایسا سلسلہ قائم کیا کہ جس سے انسان خود بھی سیراب ہوتے ہیں اور اپنے کھیتوں کو بھی سیراب کرتے ہیں جن سے انواع و اقسام کے غلے اور پھل پیدا ہوتے ہیں، جن کی شکلیں بھی ایک دوسرے سے مختلف اور ذائقے بھی جداگانہ ہوتے ہیں۔\n[2] اس کا ایک مطلب تو یہ ہے کہ نر مادہ دونوں بنائے، جیسا کہ موجودہ تحقیقات نے بھی اس کی تصدیق کر دی ہے۔ دوسرا مطلب (جوڑے جوڑے کا) یہ ہے میٹھا اور کھٹا، سرد اور گرم، سیاہ اور سفید اور ذائقہ، اس طرح ایک دوسرے سے مختلف اور متضاد قسمیں پیدا کیں۔",
      "footnotesEn": null,
