      "arFull": "الَّذِیْنَ یُوْفُوْنَ بِعَهْدِ اللّٰهِ وَلَا یَنْقُضُوْنَ الْمِیْثَاقَ ۟ۙ",
      "ur": "جو اللہ کے عہد (وپیمان) کو پورا کرتے ہیں [1] اور قول وقرار کو توڑتے نہیں.[2]",
      "en": "Those who fulfill the covenant of Allāh and do not break the contract,",
      "footnotesUr": "[1] یہ اہل دانش کی صفات بیان کی جا رہی ہیں، اللہ کے عہد سے مراد، اس کے احکام (اوامر و نواہی) ہیں جنہیں بجا لاتے ہیں۔ یا وہ عہد ہے، جو عَھْدِ الَسْت کہلاتا ہے، جس کی تفصیل سورہ اعراف میں گزر چکی ہے۔\n[2] اس سے مراد وہ باہمی معاہدے اور وعدے ہیں جو وہ آپس میں ایک دوسرے سے کرتے ہیں یا وہ جو ان کے اور ان کے رب کے درمیان ہیں۔",
