      "arFull": "وَیَقُوْلُ الَّذِیْنَ كَفَرُوْا لَوْلَاۤ اُنْزِلَ عَلَیْهِ اٰیَةٌ مِّنْ رَّبِّهٖ ؕ قُلْ اِنَّ اللّٰهَ یُضِلُّ مَنْ یَّشَآءُ وَیَهْدِیْۤ اِلَیْهِ مَنْ اَنَابَ ۟ۖۚ",
