      "en": "Those who have believed and done righteous deeds - a good state is theirs and a good return.",
      "footnotesUr": "[1] طُوْبٰی کے مختلف معانی بیان کئے گئے ہیں مثلاً خیر، حسنٰی، کرامت، رشک، جنت میں مخصوص درخت یا مخصوص مقام وغیرہ مفہوم سب کا ایک ہی ہے یعنی جنت میں اچھا مقام اور اس کی نعمتیں اور لذتیں۔",
