      "number": 39,
      "arFull": "یَمْحُوا اللّٰهُ مَا یَشَآءُ وَیُثْبِتُ ۖۚ وَعِنْدَهٗۤ اُمُّ الْكِتٰبِ ۟",
      "ur": "اللہ جو چاہے مٹا دے اور جو چاہے ﺛابت رکھے، لوح محفوظ اسی کے پاس ہے.[1]",
      "en": "Allāh eliminates what He wills or confirms, and with Him is the Mother of the Book.[644]",
      "footnotesUr": "[1] اس کے ایک معنی تو یہ ہیں وہ جس حکم کو چاہے منسوخ کردے اور جسے چاہے باقی رکھے۔ دوسرے معنی یہ ہیں اس نے جو تقدیر لکھ رکھی ہے، اس میں محو و اثبات کرتا رہتا ہے، اس کے پاس لوح محفوط ہے۔ اس کی تائید بعض احادیث و آثار سے ہوتی ہے۔ مثلاً ایک حدیث میں آتا ہے کہ ”آدمی گناہوں کی وجہ سے رزق سے محروم کر دیا جاتا ہے، دعا سے تقدیر بدل جاتی ہے اور صلہ رحمی سے عمر میں اضافہ ہوتا ہے“ (مسند احمد جلد۔5 ص۔277) بعض صحابہ سے یہ دعا منقول ہے «اللَّهُمَّ إِنْ كُنْتَ كَتَبْتَنَا أَشْقِيَاءَ فَامْحُنَا وَاكْتُبْنَا سُعَدَاءَ، وَإِنْ كُنْتَ كَتَبْتَنَا سُعَدَاءَ فَأَثْبِتْنَا، فَإِنَّكَ تَمْحُو مَا تَشَاءُ وَتُثْبِتُ وَعِنْدَكَ أُمُّ الْكِتَابِ» حضرت عمر (رضي الله عنه) سے منقول ہے کہ وہ دوران طواف روتے ہوئے یہ دعا پڑھتے ـ«اللَّهُمَّ إِنْ كُنْتَ كَتَبْتَ عَلَيّ شِقْوَةً أَوْ ذَنْبًا فَامْحُهُ، فَإِنَّكَ تَمْحُو مَا تَشَاءُ وَتُثْبِتُ وَعِنْدَكَ أُمُّ الْكِتَابِ فَاجْعَلْهُ سَعَادَةً وَمَغْفِرَةً»۔( ابن کثیر)۔ ”اے اللہ اگر تو نے مجھ پر بدبختی اور گناہ لکھا ہے تو اسے مٹا دے، اس لئے کہ تو جو چاہے مٹائے اور جو چاہے باقی رکھے، تیرے پاس ہی لوح محفوظ ہے، پس تو بدبختی کو سعادت اور مغفرت سے بدل دے“۔ اس مفہوم پر یہ اعتراض ہو سکتا ہے کہ حدیث میں تو آتا ہے «جَفَّ الْقَلَمُ بِمَا هُوَ كَائِنٌ»۔ (صحیح بخاری نمبر 5076)۔ ”جو کچھ ہونے والا ہے قلم اسے لکھ کر خشک ہو چکا ہے“ اس کا جواب یہ دیا گیا کہ یہ محو واثبات بھی منجملہ قضاء وتقدیر ہی کے ہے۔( فتح القدیر)۔",
      "footnotesEn": "[644] The Preserved Slate (al-Lawḥ al-Maḥfūẓ), in which is inscribed the original of every scripture revealed by Allāh.",
