      "arFull": "اَوَلَمْ یَرَوْا اَنَّا نَاْتِی الْاَرْضَ نَنْقُصُهَا مِنْ اَطْرَافِهَا ؕ وَاللّٰهُ یَحْكُمُ لَا مُعَقِّبَ لِحُكْمِهٖ ؕ وَهُوَ سَرِیْعُ الْحِسَابِ ۟",
      "ur": "کیا وه نہیں دیکھتے؟ کہ ہم زمین کو اس کے کناروں سے گھٹاتے چلے آرہے ہیں[1] ، اللہ حکم کرتا ہے کوئی اس کے احکام پیچھے ڈالنے واﻻ نہیں[2]، وه جلد حساب لینے واﻻ ہے.",
