      "arFull": "وَیَقُوْلُ الَّذِیْنَ كَفَرُوْا لَسْتَ مُرْسَلًا ؕ قُلْ كَفٰی بِاللّٰهِ شَهِیْدًا بَیْنِیْ وَبَیْنَكُمْ ۙ وَمَنْ عِنْدَهٗ عِلْمُ الْكِتٰبِ ۟۠",
      "ur": "یہ کافر کہتے ہیں کہ آپ اللہ کے رسول نہیں۔ آپ جواب دیجئے کہ مجھ میں اور تم میں اللہ گواہی دینے واﻻ کافی ہے[1] اور وه جس کے پاس کتاب کا علم ہے.[2]",
